/* V12 documented PI30 settings, values taken from public settings.py */
const char baison_settings_page[] =
"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>BAISON W70 | إعدادات الإنفرتر</title><style>"
":root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d1527;color:#eef4ff;font:15px Tahoma,Arial;line-height:1.7}.wrap{max-width:660px;margin:auto;padding:24px 16px}header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:18px;border-bottom:1px solid #304460}h1{font-size:22px;margin:0}h2{font-size:17px}.card{background:#1b2940;border:1px solid #304460;border-radius:16px;padding:19px;margin-top:18px}label{display:block;margin:15px 0 6px}input,select{width:100%;padding:13px;border:1px solid #435b7b;background:#101b30;border-radius:10px;color:#eef4ff;font:inherit}button,a.btn{display:inline-block;border:0;background:#31cbb3;color:#09242e;border-radius:10px;padding:11px 16px;font-weight:bold;text-decoration:none;cursor:pointer;font:inherit}a{color:#7ce9d7}small{color:#b0bfd3}pre{white-space:pre-wrap;word-break:break-all;background:#0f1e32;padding:12px;border-radius:10px;direction:ltr;text-align:left}.alert{padding:11px;background:#403019;color:#ffdf9d;border:1px solid #846634;border-radius:9px}.buttons{display:flex;gap:10px;margin-top:18px;flex-wrap:wrap}"
"</style></head><body><main class=\"wrap\"><header><h1>إعدادات الإنفرتر • V12</h1><a href=\"/\">رجوع إلى Wi-Fi</a></header>"
"<div class=\"card\"><h2>تعديل إعدادات التشغيل والشحن</h2><p class=\"alert\">تغيير نوع البطارية أو جهد الشحن أو تيار الشحن أو جهد الخرج قد يسبب ضرراً للأجهزة. راجع إعدادات البطارية والـBMS قبل التنفيذ.</p>"
"<label>الإعداد</label><select id=\"setting\"></select><small id=\"desc\"></small>"
"<label>القيمة</label><select id=\"choice\"></select><input id=\"free\" style=\"display:none\" placeholder=\"القيمة\"><small id=\"range\"></small>"
"<label>رمز إذن التعديل المحلي</label><input id=\"pin\" maxlength=\"6\" inputmode=\"numeric\" placeholder=\"من AT+BAISONWRITE=ON عبر BLE\"><small>رمز تعديل الإعدادات فقط؛ تحديث Firmware لا يتطلب رمزاً.</small>"
"<div class=\"buttons\"><button onclick=\"writeSetting()\">إرسال التعديل بعد التأكيد</button><a class=\"btn\" style=\"background:#293e5a;color:white\" href=\"/api/read?cmd=QPIRI\">عرض القيم الحالية</a></div>"
"<pre id=\"answer\">جاهز.</pre><small>تتحقق القطعة من نوع الأمر والمجال، ثم تبحث عن ACK وتقرأ QPIRI أو QFLAG بعد التنفيذ. لا تعتبر ACK وحده إثباتاً لتغير الإعداد.</small></div>"
"<div class=\"card\"><h2>أوامر القراءة الأخرى</h2><p>تتوفر قراءة البروتوكول والأجهزة وحالة البطارية مباشرة من صفحة الأوامر.</p><a href=\"/api/commands\">قائمة الأوامر المدعومة</a></div></main>"
"<script>"
"const items=["
"['output_priority','أولوية تغذية الأحمال','POP','choice',[['0','USB — الكهرباء أولاً'],['1','SOL — الشمس أولاً'],['2','SBU — الشمس ثم البطارية']]],"
"['charger_priority','أولوية الشحن','PCP','choice',[['1','CSO — الشمس أولاً'],['2','SNU — الشمس والكهرباء'],['3','OSO — الشمس فقط']]],"
"['input_range','مدى الكهرباء المقبولة','PGR','choice',[['0','APL — واسع'],['1','UPS — ضيق']]],"
"['battery_type','نوع البطارية','PBT','choice',[['0','AGM'],['1','Flooded'],['2','User'],['3','Pylontech'],['4','Shinheung'],['5','WECO'],['6','Soltaro'],['7','BAK'],['8','LIB'],['9','LIC']]],"
"['back_to_grid','الرجوع إلى كهرباء الشبكة','PBCV','voltage','22.0–28.0'],"
"['back_to_battery','الرجوع إلى البطارية','PBDV','voltage','24.0–30.0'],"
"['battery_cutoff','فولت الفصل المنخفض','PSDV','voltage','21.0–25.0'],"
"['bulk_voltage','فولت الشحن الرئيسي','PCVV','voltage','25.0–31.5'],"
"['float_voltage','فولت الشحن العائم','PBFT','voltage','25.0–31.5'],"
"['max_charge','أقصى تيار شحن كلي','MNCHGC','current','10–120 A'],"
"['max_utility_charge','أقصى تيار شحن من الشبكة','MUCHGC','current','2–120 A'],"
"['output_frequency','تردد الخرج','F','direct',[['50','50 Hz'],['60','60 Hz']]],"
"['output_voltage','جهد الخرج','V','direct',[['220','220 V'],['230','230 V'],['240','240 V']]],"
"['pv_balance','موازنة طاقة الألواح','PSPB','choice',[['0','حد وفق الشحن'],['1','شحن وأحمال']]],"
"['pv_ok','اشتراط توفر الألواح للتوازي','PPVOKC','choice',[['0','جهاز واحد يكفي'],['1','الكل لديه ألواح']]],"
"['flag_beep','صفارة الإنذار','PE','flag',[['a','تفعيل'],['!a','تعطيل']]],"
"['flag_backlight','إضاءة الشاشة','PE','flag',[['x','تفعيل'],['!x','تعطيل']]],"
"['flag_overload','التجاوز عند زيادة الحمل','PE','flag',[['b','تفعيل'],['!b','تعطيل']]]"
"];"
"const $=id=>document.getElementById(id),set=$('setting');"
"items.forEach((item,i)=>{let o=document.createElement('option');o.value=i;o.textContent=item[1];set.append(o)});"
"function refresh(){let it=items[+set.value],c=$('choice'),free=$('free');c.replaceChildren();let custom=typeof it[4]==='string';free.style.display=custom?'block':'none';c.style.display=custom?'none':'block';$('range').textContent=custom?'القيم المسموحة: '+it[4]:'اختر القيمة المطلوبة';$('desc').textContent=it[2];if(!custom){it[4].forEach(([v,t])=>{let o=document.createElement('option');o.value=v;o.textContent=t;c.append(o)})}}"
"set.onchange=refresh;refresh();"
"function command(){let item=items[+set.value],v=(typeof item[4]==='string' ? $('free').value.trim() : $('choice').value);if(!v)return '';"
"if(item[3]==='choice')v=v.padStart(2,'0');"
"if(item[3]==='current')v=String(Number(v)).padStart(3,'0');"
"if(item[3]==='voltage')v=Number(v).toFixed(1);"
"if(item[3]==='flag')return (v[0]==='!'?'PD':'PE')+v.replace('!','');"
"return item[2]+v;}"
"async function writeSetting(){let cmd=command(),pin=$('pin').value,box=$('answer');if(!cmd){box.textContent='أدخل القيمة';return}"
"if(!/^\\d{6}$/.test(pin)){box.textContent='يلزم رمز تعديل مكون من 6 أرقام من البلوتوث';return}"
"if(!confirm('تأكيد تنفيذ '+cmd+' على الإنفرتر؟ قد يتغير وضع الكهرباء أو البطارية.'))return;"
"box.textContent='جار الإرسال والتحقق...';"
"try{let r=await fetch('/api/inverter/write',{method:'POST',headers:{'X-W70-Action':'confirm'},body:new URLSearchParams({command:cmd,pin})});let t=await r.text();box.textContent=t; }catch(e){box.textContent=String(e)}}"
"</script></body></html>";
